-- Dividir a conta (F4-0061): the five ways to split a bill, recorded.
--   itens_comanda.assento   optional seat (1 to 99) the item belongs to; the split by seat groups by it. Null = shared by all the seats.
--   divisoes                one row per recorded split of a comanda. id is generated by the client (idempotent). assinatura fingerprints what the bill was made of (items with lines and seats, discounts, fee
--                           rule): when the comanda changes afterwards it no longer matches and the split is invalid. total_centavos is the bill (consumption after discounts plus service fee) the parts add up
--                           to; gorjeta_centavos is the tip, outside the bill. Written once (the app credential has only SELECT and INSERT).
--   divisao_partes          the parts of a split (numero 1..n, stable order). A later payment references (divisao_id, numero). item_ids lists the items of the part (seat and item modes).
-- Everything is tenant data: exact RLS, composite FKs (a split of another organization, unit or comanda is refused).
ALTER TABLE itens_comanda ADD COLUMN assento integer CHECK (assento BETWEEN 1 AND 99);

CREATE TABLE divisoes (
  id                      uuid PRIMARY KEY,
  organizacao_id          uuid        NOT NULL REFERENCES organizacoes (id),
  unidade_id              uuid        NOT NULL,
  comanda_id              uuid        NOT NULL,
  modo                    text        NOT NULL CHECK (modo IN ('iguais', 'assento', 'item', 'valores', 'percentual')),
  comanda_versao          integer     NOT NULL CHECK (comanda_versao >= 1),
  assinatura              text        NOT NULL CHECK (length(assinatura) = 64),
  total_centavos          bigint      NOT NULL CHECK (total_centavos >= 0),
  taxa_servico_centavos   bigint      NOT NULL CHECK (taxa_servico_centavos >= 0),
  gorjeta_centavos        bigint      NOT NULL CHECK (gorjeta_centavos >= 0),
  criado_por              uuid        NOT NULL,
  criado_em               timestamptz NOT NULL,
  UNIQUE (organizacao_id, id),
  FOREIGN KEY (organizacao_id, unidade_id) REFERENCES unidades (organizacao_id, id),
  FOREIGN KEY (organizacao_id, comanda_id) REFERENCES comandas (organizacao_id, id),
  FOREIGN KEY (organizacao_id, criado_por) REFERENCES contas (organizacao_id, id)
);

CREATE INDEX divisoes_por_comanda ON divisoes (organizacao_id, comanda_id, criado_em, id);

CREATE TABLE divisao_partes (
  organizacao_id         uuid     NOT NULL REFERENCES organizacoes (id),
  divisao_id             uuid     NOT NULL,
  numero                 integer  NOT NULL CHECK (numero BETWEEN 1 AND 50),
  assento                integer  CHECK (assento BETWEEN 1 AND 99),
  item_ids               uuid[]   NOT NULL,
  consumo_centavos       bigint   NOT NULL CHECK (consumo_centavos >= 0),
  taxa_servico_centavos  bigint   NOT NULL CHECK (taxa_servico_centavos >= 0),
  total_centavos         bigint   NOT NULL CHECK (total_centavos = consumo_centavos + taxa_servico_centavos),
  gorjeta_centavos       bigint   NOT NULL CHECK (gorjeta_centavos >= 0),
  PRIMARY KEY (organizacao_id, divisao_id, numero),
  FOREIGN KEY (organizacao_id, divisao_id) REFERENCES divisoes (organizacao_id, id)
);

ALTER TABLE divisoes ENABLE ROW LEVEL SECURITY;
ALTER TABLE divisoes FORCE  ROW LEVEL SECURITY;
CREATE POLICY isolamento ON divisoes
  USING (organizacao_id = (SELECT app_organizacao_id()))
  WITH CHECK (organizacao_id = (SELECT app_organizacao_id()));

ALTER TABLE divisao_partes ENABLE ROW LEVEL SECURITY;
ALTER TABLE divisao_partes FORCE  ROW LEVEL SECURITY;
CREATE POLICY isolamento ON divisao_partes
  USING (organizacao_id = (SELECT app_organizacao_id()))
  WITH CHECK (organizacao_id = (SELECT app_organizacao_id()));

REVOKE UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON divisoes FROM flow4tech_app;
REVOKE ALL ON divisoes FROM PUBLIC;
REVOKE UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON divisao_partes FROM flow4tech_app;
REVOKE ALL ON divisao_partes FROM PUBLIC;
